    description:
      '■ 원로목사님 동정 : 합동, 통합, 고신, 합신 총회에서 2027 8천만 민족 복음화 대성회를 위한 설명회를 진행하시고, 강사단 회의를 인도하십니다.\n\n■ 예배와 소식\n\n1. 오늘 5부 예배는 함동노회 남전도회 연합회 헌신 예배로 드립니다.\n\n2. 다음주 5부 예배는 리더십 강의로 진행됩니다. 모든 리더들은 꼭 참석해 주시기 바랍니다.\n\n3. 하반기 전도 사역이 진행 중입니다. 기도로 준비하시고 적극 동참해 주시기 바랍니다.\n◆ 노방전도 : 매주 화요일 오후 2시 장소 : 1층 휴게실\n◆ 청소전도 : 매주 토요일 오전 11시 장소 : 주차장\n\n4. 실버 대학이 진행 중입니다. 본당 로비에 비치된 신청서를 작성하여 접수함에 제출해 주시기 바랍니다.\n많은 관심과 참여 부탁드립니다.\n\n5. 교회 차량은 깨끗하게 이용해주시고 사용 전에 꼭 차량 사용 대장을 기입해 주시기 바랍니다.\n성도님들의 협조가 차량 관리에 큰 도움이 됩니다.\n\n6. 교회 앞 도로변에 주차하신 후에는, 횡단보도로 건너셔서 무단 횡단을 하지 않도록\n각별히 주의해 주시기 바랍니다.\n\n7. 쓰레기를 버릴 때 음료와 음식물은 정리해주시고, 분리수거에 힘써 주시기 바랍니다.\n\n8. 2026년 성경 일독이 진행되고 있습니다. 아래의 표를 참고해 주시기 바랍니다.\n13일(주일) · 14일(월) · 15일(화) · 16일(수) · 17일(목) · 18일(금) · 19일(토)\n겔 38-40 · 겔 41-43 · 겔 44-46 · 겔 47-단1 · 단 2-6 · 단 7-9 · 단 10-12\n﻿\n9. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면\n모든 예배를 실시간으로 드리실 수 있습니다.\n메시지는 매주 업데이트 되고, 구독과 청취가 신앙 성숙과\n교회 홍보 그리고 복음 전파에 많은 도움이 됩니다.',
