      '★ 성복교회 교육부서 여름 사역 안내 ★\n·영아부 7/11(토)-12(주일), 19(주일) 사랑성전 · ·중등부 7/25(토)-26(주일) 팀수양관\n·유치부 7/12(주일), 19(주일), 25(토)-26(주일) 믿음성전 · ·고등부 7/25(토)-26(주일) 팀수양관\n·유년부 7/24(금)-26(주일) 소망성전 · ·영어예배부 8/6(목)-8(토) 천안국립중앙청소년수련원\n·초등부 7/17(금)-19(주일) 화평성전 · ·청년부 8/17(월)-19(수) 오륜비전빌리지\n\n■ 원로목사님 동정 : 2027 8천만 민족 복음화 대성회를 위한 오산리 기도원 성회를 인도하십니다.\n\n■ 예배와 소식\n\n1. 교육부 여름 사역이 진행 중 입니다. 성도님들의 많은 관심과 기도 부탁드립니다.\n\n2. 모든 구역들은 소그룹 활성화를 위해 은혜 나눔 모임에 힘써 주시기 바랍니다.\n\n3. 지하 식당의 낙후된 기도실을 소그룹실로 전환하는 리모델링 공사가 7월 20일(월)부터 시작됩니다.\n성도님들의 많은 기도와 헌신 부탁드립니다.\n\n4. 주일 예배 후에 성도들의 교제를 더욱 풍성하게 할 주방 봉사자분들을 모집합니다.\n기쁜 마음으로 섬기실 분들의 많은 관심과 지원 부탁드립니다.\n- 봉사 내용 : 주일 점심 식사 준비 및 배식, 정리\n- 신청 및 문의 : 이명배 장로(010-8930-3456), 최복기 권사(010-2847-4421)\n\n5. 청년부 소그룹 활동을 위해 1층과 지하 소그룹 실은 모임을 오후 2시 50분까지 종료해 주시기 바랍니다.\n\n6. 고유가 시대에 에너지 절약을 위한 교회 시설 이용 안내입니다.\n- 모든 모임 후에는 전등 및 냉방기 스위치를 점검하고 퇴실해 주시기 바랍니다.\n- 여름철 적정 실내 온도를 준수해 주시기 바랍니다.(26°C~28°C)\n\n7. 2026년 성경 일독이 진행되고 있습니다. 아래의 표를 참고해 주시기 바랍니다.\n12일(주일) · 13일(월) · 14일(화) · 15일(수) · 16일(목) · 17일(금) · 18일(토)\n잠5-7 · 잠8-10 · 잠11-13 · 잠14-16 · 잠17-21 · 잠22-24 · 잠25-27\n﻿\n8. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면\n모든 예배를 실시간으로 드리실 수 있습니다.\n메시지는 매주 업데이트 되고, 구독과 청취가 신앙 성숙과\n교회 홍보 그리고 복음 전파에 많은 도움이 됩니다.',
