      '■ 원로목사님 동정 : 민족복음화운동본부 파주DMZ본부 발대식 및 대표본부장 임원취임식과 부천본부 발대식 및 대표본부장 임원 취임식을 인도하십니다.\n\n■ 예배와 소식\n\n1. 3월 월삭예배가 2일(월) 오전 5시 30분, 3층 임마누엘 성전에서 있습니다.\n\n2. 3월 8일(주일)부터 예배시간이 변경됩니다. (※ 칼럼란 참조)\n\n3. 이번 주 금요생수의 강 예배는 응답 선교회를 이끌고 계신 이금자 사모님께서 말씀을 전해주십니다.\n\n4. 상반기 학습‧세례교육(유아세례)이 진행중 입니다.\n◆ 교육시간 : 주일 1부 예배 후 / 3부 예배 후\n◆ 장소 : 세례, 입교(3층 임마누엘 성전), 학습(1층 A모임실), 유아세례(1층 영아부실)\n\n5. 모든 교구는 소그룹 활성화를 위해 힘써 주시기 바랍니다.\n\n6. 실버대학을 섬겨주실 봉사자를 모집합니다. 성도님들의 많은 관심과 참여 부탁드립니다.\n◆ 모집분야 : 식당주방봉사, 차량운행, 음향, 재능기부자\n◆ 신청/문의 : 신상훈 장로, 신미자 권사\n\n7. 춘계 대심방이 진행 중입니다. 찾아가는 가정마다 하나님의 은혜가 풍성히 임하기를 축원합니다.\n\n8. 교육부서 겨울사역이 하나님의 은혜 가운데 잘 마쳤습니다. 함께 기도해주셔서 감사합니다.\n\n9. 식당 경로석은 어르신들께 양보해 주시고 아이들과 학부모님들께서는 뒤쪽 테이블을 이용해 주시기 바랍니다.\n\n10. 해외선교 위원회에서 선교 저금통 나누기 행사를 시작합니다. 2주간 1층 로비에서 선교저금통을 나누어 드리며, 모금기간은 11월 첫째 주일까지입니다.\n\n11. 2026년 성경 일독이 진행되고 있습니다. 아래의 표를 참고해 주시기 바랍니다.\n3월1일(주일) · 2일(월) · 3일(화) · 4일(수) · 5일(목) · 6일(금) · 7일(토)\n수 9-11 · 수 12-14 · 수 15-17 · 수 18-20 · 수 21-삿 1 · 삿 2-4 · 삿 5-7\n\n12. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면 모든 예배를 실시간으로 드리실 수 있습니다. 메시지는 업데이트되고 구독과 청취가 신앙성숙과 교회홍보 그리고 복음전파에 많은 도움이 됩니다.\n\n■ 결 혼\n청년부 장지웅 형제와 박연주 자매의 결혼예식이 3월 7일(토) 오후 12시 30분\n웨딩스퀘어 강변 3층 베니르홀에서 있습니다.',
