    thumbnail: 'https://i.ytimg.com/vi/nrBNGOA4__0/hqdefault.jpg',
    poster: 'https://i.ytimg.com/vi/nrBNGOA4__0/maxresdefault.jpg',
    description:
      '★ 12월·1월 예배 및 행사 ★\n· 12월 28일(주일) : 주일학교 졸업식 (3부) · · 1월 1일(목) : 신년 하례식 (오전 11시)\n· 12월 31일(수) : 송구영신예배 (오후 11시) · · 1월 4일(주일) : 신년감사예배\n· 1월 9일(금)~2월 6일(금) : 신년특별부흥집회\n\n■ 원로목사님 동정 : 2027 8천만 민족복음화대성회를 위한 예성영성원 신년축복성회를 인도하십니다.\n\n■ 예배와 소식\n\n1. 오늘 리더십 강의가 5부 예배 시 진행됩니다. (차량 출발 시각은 오후 5시입니다.)\n교회의 모든 리더들은 반드시 참석해 주시기 바랍니다.\n(※ 리더십 강의는 유튜브 송출을 하지 않습니다.)\n\n2. 오늘 3부 예배 시 주일학교 졸업식이 있습니다. 다음 세대를 위해서 많은 관심과 기도 부탁드립니다,\n\n3. 송구영신예배가 수요일 오후 11시 3층 본당에서 있습니다.\n- 송구영신예배 후에는 새해를 위한 성도 전체 축복기도 시간이 있습니다.\n- 하나님과 이웃간의 관계를 잘 정리하시고 가족 단위로 질서 있게 기도 받으시길 바랍니다.\n- 2026년 우리 가정 기도 제목 카드를 ‘송구영신예배’ 참석 시 들어오시면서 제출해 주시기 바랍니다.\n\n4. 이번 주 수요예배는 송구영신예배로 대체됩니다.\n\n5. 복지위원회에서 주관하는 연말 사랑의 쌀 나누기 행사가 1층 로비에서 있습니다.\n\n6. 신년 하례식이 1월 1일(목) 오전 11시에 1층 영아부실에서 있습니다.\n\n7. 다음 주일은 신년 감사주일로 드립니다.\n\n8. 신년 특별부흥집회가 1월9일(금)부터 2월 6일(금)까지 진행됩니다.\n\n9. 2026년 신임 서리집사가 임명되었습니다. (※ 칼럼란 참조)\n\n10. 2025년 성경 일독이 수요일로 마무리됩니다. 완료하신 분들께서는 성경 읽기표를 교회 사무실에 제출하시면 소정의 상품을 드립니다.\n\n11. 2025년 한 해를 되돌아보고 대신, 대물, 대인 관계를 회개와 행함으로 잘 마무리 하시고 나라와 민족을 위해서 기도하는 성도님들 되시기를 바랍니다.\n\n12. 2026년에도 성경 일독이 계속 진행됩니다. 1층 로비에 비치된 성경 읽기표를 참고하셔서 통독에 힘써 주시기 바랍니다.\n28일(주일) · 29일(월) · 30일(화) · 31일(수) · 1월 1일(목) · 2일(금) · 3일(토)\n계 15-16 · 계 17-18 · 계 19-20 · 계 21-22 · 창 1-5 · 창 6-8 · 창 9-11\n\n13. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면 모든 예배를 실시간으로 드리실 수 있습니다. 메시지는 업데이트되고 구독과 청취가 신앙성숙과 교회홍보 그리고 복음전파에 많은 도움이 됩니다.',
