      '■ 원로목사님 동정 : 제4차 성령의 새연합 컨퍼런스를 인도하십니다.\n\n■ 예배와 소식\n\n1. 12월 월삭예배가 내일 오전 5시 30분, 3층 임마누엘 성전에서 있습니다.\n은혜의 말씀으로 한 달을 능력 있게 시작하시는 성도들이 되시기를 진심으로 기원합니다.\n\n2. 다음 주 5부 예배시 직분자 은퇴식이 있습니다. (강사 : 원로 목사님)\n장 로 : 김철기, 신현궁\n안수집사 : 김상곤\n권 사 : 강상분, 김금덕, 김나영B, 김옥태, 김인숙, 문영숙, 박화숙, 배윤례, 서혜자, 손옥자, 신귀녀, 이정례, 전삼순, 정은혜, 최양자, 황인순\n\n3. 각 교육부서에서 주일학교 교사를 모집합니다.\n(문의 - 교육위원회 총무 허재혁 집사 : 010-4236-0227)\n\n4. 해외선교위원회에서 나누어드렸던 선교저금통을 회수하고, 2025년 성탄선물을 선교지에\n보내기 위한 후원금을 오늘까지 모금합니다.\n\n5. 복지위원회에서 주관하는 연말 사랑의 쌀 나누기를 위한 모금행사가 있습니다.\n◆ 일시 : 12월 7일, 14일, 21일, 25일 ◆ 장소 : 1층 로비\n\n6. 하반기 노방전도와 청소전도를 은혜 가운데 마쳤습니다.\n\n7. 2025년 성경 일독이 진행 중입니다. 아래의 표를 참고하셔서 1년간 성경을 통독하시기 바랍니다.\n30일(주일) · 12월 1일(월) · 2일(화) · 3일(수) · 4일(목) · 5일(금) · 6일(토)\n갈 5-엡 1 · 엡 2-4 · 엡 5-빌 1 · 빌 2-골 2 · 골3-살전 1 · 살전 2-살전 4 · 살전 5-살후 2\n\n8. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면\n모든 예배를 실시간으로 드리실 수 있습니다.\n메시지는 업데이트되고 구독과 청취가 신앙성숙과\n교회홍보 그리고 복음전파에 많은 도움이 됩니다.',
