      '■ 원로목사님 동정 : 민족복음화운동본부 특별연수 및 임원 워크샵과 감람산기도원 집회 그리고 부울경 부흥목회연구원 강의를 인도하십니다.\n\n■ 예배와 소식\n\n1. 오늘 4부 예배는 임마누엘 성전에서 드립니다.\n\n2. 오늘 5부 예배 시에는 연합남전도회 찬양대회가 있습니다.\n\n3. 오늘은 젊은 부부 DAY (Potluck Party)가 있습니다.\n◆ 대상 : 2040 젊은 부부 전체 ◆ 시간 : 오후 2시 50분 / 장소 : 지하 식당\n\n4. 이번 주 금요생수의강 예배는 가을특별 부흥집회로 드립니다. (※ 칼럼란 참조)\n모두 참석하셔서 풍성한 은혜를 누리시기 바랍니다. (강사 : 박지헌 집사(V.O.S) / 굿네이버스 대사)\n\n5. 하반기 학습·세례교육(유아세례포함)이 진행 중입니다.\n◆ 교육시간 : 주일 1부 예배 후 / 3부 예배 후\n◆ 장소 : 세례,입교 (3층 임마누엘 성전), 학습 (1층 A모임실), 유아세례(1층 영아부실)\n\n6. 학습, (유아)세례식이 다음 주 2,3부 예배 시 본당에서 있습니다.\n해당되는 분들은 단정한 복장으로 예배 30분 전까지 모여주시기 바랍니다.\n\n7. 교구와 주일학교의 새생명 전도축제가 진행 중입니다. 함께 기도해 주시고 전도에 힘써주시기 바랍니다.\n교구 · 1교구 · 2교구 · 3교구 · 4교구 · 5교구 · 6교구 · 엘림가족부\n일시 · 11월 23일 · 11월 16일 · 11월 23일 · 11월 9일 · 11월 9일 · 11월 9일 · 10월 26일\n\n부서 · 영아부 · 유치부 · 유년부 · 초등부 · 중등부 · 고등부 · 영어예배부 · 청년부\n일시 · 10월 26일 · 10월 26일 · 11월 2일 · 11월 9일 · 10월 26일 · 10월 26일 · 11월 9일 · 11월 9일\n\n8. 임마누엘 성전 보수공사로 스크린, 조명, 카메라 교체가 진행될 예정입니다.\n성도님들의 많은 기도와 헌신을 부탁드립니다.\n\n9. 교회차량 관리 및 운전하실 분을 구합니다.\n◆ 자격요건 : 대형면허 소지자 (※ 문의 : 사무장 용봉식 장로 010-3749-6375)\n\n10. 2025년 성경 일독이 진행 중입니다. 아래의 표를 참고하셔서 1년간 성경을 통독하시기 바랍니다.\n26일(주일) · 27일(월) · 28일(화) · 29일(수) · 30일(목) · 31일(금) · 11월 1일(토)\n눅 8-10 · 눅 11-13 · 눅 14-16 · 눅 17-21 · 눅 22 - 24 · 요 1-3 · 요 4-6\n\n11. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면 모든 예배를 실시간으로 드리실 수 있습니다. 메시지는 업데이트되고 구독과 청취가 신앙성숙과 교회홍보 그리고 복음전파에 많은 도움이 됩니다.\n\n12. 결혼 : 4교구 김성식 집사, 유미정 집사의 장남 김영준군의 결혼예식이 11월 1일 토요일 우리들교회 판교 채플 8층 탄설홀에서 있습니다.',
