      '■ 원로목사님 동정 : 2027 8천만 민족복음화대성회 남경산기도원 대성회를 인도하십니다.\n\n■ 예배와 소식\n\n1. 8/30(토)까지 가정예배 집중기간입니다.\n하반기 사역을 위해 지금부터 기도로 준비해주시기 바랍니다.\n\n2. 교육부서(유치부, 유년부) 성전 리모델링이 진행 중입니다.\n성도님들의 많은 기도와 헌신을 부탁드립니다.\n\n3. 유치부와 유년부 예배장소가 리모델링 기간동안 변경됩니다.\n부서명 · 장소 · 사용시간\n유치부 · 3층 임마누엘 성전 · 오전 10:30 – 오후 12:30\n유년부 · 1층 휴게실 · 오전 10:30 – 오후 12:30\n* 1층 아카페와 소그룹실은 유년부 사용시간 동안 운영하지 않습니다.\n\n4. 해외선교위원회에서 9월25일(목)~27일(토) 일본 단기 선교를 진행합니다.\n(장소 : 고베은혜교회 / 홍덕표 선교사)\n\n5. 각 부서 및 위원회 모임 후 냉방 스위치를 꼭 점검하고 퇴실해 주시기 바랍니다.\n(※여름철 실내 적정 온도26°C를 유지하셔서 에너지 절약에 동참해 주시기 바랍니다.)\n\n6. 2025년 성경 일독이 진행 중입니다. 아래의 표를 참고하셔서 1년간 성경을 통독하시기 바랍니다\n24일(주일) · 25일(월) · 26일(화) · 27일(수) · 28일(목) · 29일(금) · 30일(토)\n렘 29-31 · 렘 32-34 · 렘 35-37 · 렘 38-42 · 렘 43-45 · 렘 46-48 · 렘 49-51\n\n7. 예배시간에 맞추어 YouTube 에서 성복교회를 검색하시면\n모든 예배를 실시간으로 드리실 수 있습니다.\n메시지는 업데이트되고 구독과 청취가 신앙성숙과\n교회홍보 그리고 복음전파에 많은 도움이 됩니다.',
